  "player_descriptions": {
    "9": "Robano, you were a rock in defense today! You made some crucial blocks and interceptions, helping to keep things tight at the back even though the result didn't go our way.",
    "7": "Mehtab, you showed some great attacking intent, getting a few shots away and causing problems for the opposition. It's just a shame that none of them found the back of the net, and we couldn't convert that pressure into more goals today.",
    "6": "Zunaid, you were always available to help out in both defense and attack. That's the kind of flexibility we need, keep it up champ!",
    "12": "Jamla, you were always looking to make something happen in attack, and that assist shows you have that creative spark. Keep trying those shots, the goals will come!",
    "11": "Kavin, what a fantastic performance with two goals and three assists! You were a constant threat and a real driving force in attack. Keep that up, and we'll be unstoppable!",
    "13": "Krishnan, you popped up with a goal and an assist, a fantastic contribution! Keep making those runs and getting into dangerous positions; you've got a real eye for goal.",
    "8": "Dev, you pulled off some great saves, even if the scoreline doesn't reflect your efforts. We're lucky to have you between the sticks!",
    "5": "Manesh, you were a safe pair of hands in goal, making some important saves. Keep up that concentration; we'll need you to be on top form every game!",
    "10": "Vinay, you were brilliant with two goals and an assist! Keep up those dangerous shots, you have the skill to make it count.",
    "2": "Mo, what a showing, you bagged four goals and an assist, a real captain's performance. With you leading the line like that, we'll be winning plenty more games!",
    "1": "Bhukayo, you were a real handful for the defense today, with four goals and two assists. That's the kind of performance that can really lift a team, even if we didn't get the result we wanted. Keep up the good work!",
    "4": "Kalyan, you were lethal in front of goal, scoring three goals. Keep up that kind of finishing, and you'll be a nightmare for defenders!",
    "14": "Luis, you were trying your best out there, making some decent passes and getting into good positions. Keep working on those shots, and you'll be among the goals soon enough!",
    "16": "Tarun, you found the net twice, a great effort! Keep getting in those dangerous positions, and you'll keep adding to your tally.",
    "17": "Rohan, even though you only had limited time on the pitch, we appreciate you being ready to contribute. Every player has a role to play, and your chance will come!",
    "3": "Lokesh, your interceptions and tackles were crucial in breaking up their play. You were also able to get forward to get two assists! Keep up that work rate, and you'll be a key player for us.",
    "15": "Nikhil, you got a goal, an assist, and a solid defensive presence! Your work rate was fantastic, and you really helped to protect the defense."
  },
  "match_description": "What a match we've just witnessed! Ballers for Life absolutely dismantled Street Legends in a 14-5 victory! Mo Swaha led the charge with a blistering four goals, while Kalyan Mbappi bagged a hat trick of his own, adding insult to injury. Street Legends did have Bhukayo Sarkar who fought bravely, notching four goals for his squad, but it wasn't nearly enough to contain the Ballers for Life onslaught. Kavin D'Braine also had a wonderful performance, bagging a pair and assisting on multiple other goals to really put the Street Legends to the sword!",
